import itertools

def simulate(coins, k):
    seen = set()
    while True:
        state = "".join(coins)
        if state in seen:
            return False  # Cycle detected, didn't reach sorted state
        seen.add(state)

        # Check if the configuration has at most one adjacency
        adjacencies = 0
        for i in range(len(coins) - 1):
            if coins[i] != coins[i+1]:
                adjacencies += 1
        if adjacencies <= 1:
            return True

        # Operation
        k_idx = k - 1
        metal = coins[k_idx]

        # Find the boundaries of the block containing the k-th coin
        left = k_idx
        while left > 0 and coins[left-1] == metal:
            left -= 1
        right = k_idx
        while right < len(coins) - 1 and coins[right+1] == metal:
            right += 1

        block = coins[left:right+1]
        remaining = coins[:left] + coins[right+1:]
        coins = block + remaining

def check_k(n_half, k):
    # For n_half = 2, coins = ['A', 'A', 'C', 'C']
    coins_base = ['A'] * n_half + ['C'] * n_half
    for config in itertools.permutations(coins_base):
        if not simulate(list(config), k):
            return False
    return True

for n_half in range(1, 4):
    print(f"n_half = {n_half}, N = {2*n_half}")
    for k in range(1, 2*n_half + 1):
        print(f"k = {k}: {check_k(n_half, k)}")

